// A generated annotation of a component (see constants/componentConstants.js).
export function isComponentChildAnnotation(annotation) {
  return Boolean(annotation?.componentSourceAnnotationId);
}

// Id of the component an annotation was generated by, if any.
export function getComponentSourceId(annotation) {
  return annotation?.componentSourceAnnotationId ?? null;
}

// Display copies, cached per annotation object (stable identity for the
// memoized nodes and the 3D diff).
const childNodeCache = new WeakMap();
const hiddenSourceCache = new WeakMap();

function getChildNode(child, source) {
  const sourceTemplateId = source?.annotationTemplateId ?? null;
  const cached = childNodeCache.get(child);
  if (cached && cached.sourceTemplateId === sourceTemplateId)
    return cached.node;
  const node = {
    ...child,
    systemSourceAnnotationId: child.componentSourceAnnotationId,
    ...(sourceTemplateId ? { systemSourceTemplateId: sourceTemplateId } : {}),
  };
  childNodeCache.set(child, { sourceTemplateId, node });
  return node;
}

function getHiddenSource(source) {
  let node = hiddenSourceCache.get(source);
  if (!node) {
    node = { ...source, systemSourceHidden: true };
    hiddenSourceCache.set(source, node);
  }
  return node;
}

/**
 * Display filter of the components, applied where the editors filter what
 * they draw (never in useAnnotationsV2: quantities and listings keep every
 * annotation), AFTER applySystemDisplay:
 *
 *   - component NOT selected: its children are drawn and stand for it; the
 *     source is hidden — flagged `systemSourceHidden` (2D: still in the list,
 *     so the edit layer draws it once selected) or dropped
 *     (`dropHiddenSources`, 3D);
 *   - component selected (`selectedIds`): only the source is drawn, its
 *     children are dropped;
 *   - a source without any child in the list (nothing enabled, children
 *     filtered out) is drawn as a regular annotation;
 *   - children of a source hidden for the session (`hiddenSourceIdSet`) are
 *     dropped with it.
 *
 * A child reuses the display contract of the system generated annotations —
 * it is handed over with `systemSourceAnnotationId` = its component — so
 * every hit on it (2D node, lasso, select-all, 3D pick) resolves to the
 * component, which is hovered / selected as a whole. These fields exist on
 * the display copies only, never in the database.
 *
 * Returns the input array itself when it holds no component child.
 */
export default function applyComponentDisplay(
  annotations,
  { selectedIds, hiddenSourceIdSet, dropHiddenSources = false } = {}
) {
  if (!annotations?.length) return annotations;

  let childCountBySourceId = null;
  for (const a of annotations) {
    const sourceId = a.componentSourceAnnotationId;
    if (!sourceId) continue;
    if (!childCountBySourceId) childCountBySourceId = new Map();
    childCountBySourceId.set(
      sourceId,
      (childCountBySourceId.get(sourceId) ?? 0) + 1
    );
  }
  if (!childCountBySourceId) return annotations;

  const selectedSet =
    selectedIds instanceof Set ? selectedIds : new Set(selectedIds ?? []);
  const sourceById = new Map();
  for (const a of annotations) {
    if (childCountBySourceId.has(a.id)) sourceById.set(a.id, a);
  }

  const result = [];
  for (const a of annotations) {
    const sourceId = a.componentSourceAnnotationId;
    if (sourceId) {
      if (selectedSet.has(sourceId)) continue;
      if (hiddenSourceIdSet?.has(sourceId)) continue;
      result.push(getChildNode(a, sourceById.get(sourceId)));
      continue;
    }
    if (childCountBySourceId.has(a.id) && !selectedSet.has(a.id)) {
      if (!dropHiddenSources) result.push(getHiddenSource(a));
      continue;
    }
    result.push(a);
  }
  return result;
}
